{
  "name": "github-oauth-integration",
  "version": "1.0.0",
  "description": "GitHub OAuth integration for existing Express app",
  "main": "server.js",
  "scripts": {
    "start": "node server.js",
    "dev": "nodemon server.js"
  },
  "dependencies": {
    "dotenv": "^16.4.5",
    "express": "^4.19.2",
    "express-session": "^1.18.0",
    "passport": "^0.7.0",
    "passport-github2": "^0.1.12"
  },
  "devDependencies": {
    "nodemon": "^3.1.4"
  }
}

const express = require('express');
const passport = require('passport');
const GitHubStrategy = require('passport-github2').Strategy;

// NOTE: Replace this with your actual DB query logic
async function findOrCreateUser(githubProfile) {
  const email = githubProfile.emails?.[0]?.value || githubProfile.username + '@github.com';

  // Example with raw SQL (pg/mysql/sqlite):
  // const result = await db.query('SELECT * FROM users WHERE email = ?', [email]);
  // let user = result.rows[0];
  // if (!user) {
  //   const insert = await db.query(
  //     'INSERT INTO users (email, created_at) VALUES (?, NOW()) RETURNING *',
  //     [email]
  //   );
  //   user = insert.rows[0];
  // }
  // return user;

  // Mock for demonstration:
  return {
    id: githubProfile.id,
    email: email,
    created_at: new Date().toISOString()
  };
}

passport.use(new GitHubStrategy({
    clientID: process.env.GITHUB_CLIENT_ID,
    clientSecret: process.env.GITHUB_CLIENT_SECRET,
    callbackURL: process.env.GITHUB_CALLBACK_URL || 'http://localhost:3000/auth/github/callback',
    scope: ['user:email']
  },
  async (accessToken, refreshToken, profile, done) => {
    try {
      const user = await findOrCreateUser(profile);
      return done(null, user);
    } catch (err) {
      return done(err);
    }
  }
));

// Serialize only the user id into the session (works with your existing express-session)
passport.serializeUser((user, done) => {
  done(null, user.id);
});

// Deserialize user from session by id
// NOTE: Replace db.query with your actual database lookup
passport.deserializeUser(async (id, done) => {
  try {
    // Example: const result = await db.query('SELECT id, email, created_at FROM users WHERE id = ?', [id]);
    // const user = result.rows[0];
    // done(null, user);

    // Mock for demonstration:
    done(null, { id });
  } catch (err) {
    done(err);
  }
});

const router = express.Router();

// 1. Redirect to GitHub
router.get('/github',
  passport.authenticate('github', { scope: ['user:email'] })
);

// 2. GitHub redirects back here after authorization
router.get('/github/callback',
  passport.authenticate('github', { 
    failureRedirect: '/login',
    successRedirect: '/'
  })
);

// 3. Logout
router.get('/logout', (req, res, next) => {
  req.logout((err) => {
    if (err) return next(err);
    res.redirect('/');
  });
});

// 4. Get current user (useful for frontend)
router.get('/me', (req, res) => {
  if (req.isAuthenticated && req.isAuthenticated()) {
    res.json({ user: req.user });
  } else {
    res.status(401).json({ user: null });
  }
});

module.exports = { authRouter: router, passport };

require('dotenv').config();
const express = require('express');
const session = require('express-session');
const { authRouter, passport } = require('./auth');

const app = express();

// ============================================================
// YOU ALREADY HAVE THIS CONFIGURED - keep it as-is
// ============================================================
app.use(session({
  secret: process.env.SESSION_SECRET || 'your-existing-session-secret',
  resave: false,
  saveUninitialized: false,
  cookie: { secure: false } // set to true in production with HTTPS
}));

// ============================================================
// ADD THESE TWO LINES AFTER your express-session middleware
// ============================================================
app.use(passport.initialize());
app.use(passport.session());

// ============================================================
// YOUR EXISTING APP ROUTES AND MIDDLEWARE GO HERE
// ============================================================

// Mount the auth router at /auth
app.use('/auth', authRouter);

// Example protected route
app.get('/dashboard', ensureAuthenticated, (req, res) => {
  res.send(`<h1>Dashboard</h1><p>Welcome, ${req.user.email}!</p><a href="/auth/logout">Logout</a>`);
});

// Example public route
app.get('/', (req, res) => {
  if (req.isAuthenticated && req.isAuthenticated()) {
    res.send(`<h1>Home</h1><p>Hello, ${req.user.email}!</p><a href="/dashboard">Dashboard</a> | <a href="/auth/logout">Logout</a>`);
  } else {
    res.send(`<h1>Home</h1><p>You are not logged in.</p><a href="/login">Login</a>`);
  }
});

// Serve login page
app.get('/login', (req, res) => {
  res.sendFile(__dirname + '/login.html');
});

// Middleware to protect routes
function ensureAuthenticated(req, res, next) {
  if (req.isAuthenticated && req.isAuthenticated()) {
    return next();
  }
  res.redirect('/login');
}

const PORT = process.env.PORT || 3000;
app.listen(PORT, () => {
  console.log(`Server running on http://localhost:${PORT}`);
});

